__HAL_ROM_USED HAL_StatusTypeDef HAL_AUDCODEC_Config_TChanel(AUDCODEC_HandleTypeDef *hacodec, int channel, AUDCODEC_DACCfgTypeDef *cfg)
{
    AUDCODE_DAC_CLK_CONFIG_TYPE *dac_clk = cfg->dac_clk;

